// マウス押し続けチェック
if( !mouse_check_button( mb_left ) ){
  lbutton_hold = false;
}
if( !mouse_check_button( mb_right ) ){
  rbutton_hold = false;
}

if( lbutton_hold ){
  event_perform(ev_mouse, ev_left_press);
}

if( rbutton_hold && mouse_check_button( mb_right ) ){
  event_perform(ev_mouse, ev_right_press);
}
